INSERT INTO `ai_generated_exercises` VALUES (5,'2026-10-16 07:05:18.000000','2026-10-16 07:05:18.000000','A1','LISTENING_DIALOGUE','136525cc-0c13-41a1-8d51-092140eca067',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"listeningPassage\":\"Speaker A: Hi, Ben! What are you doing this weekend?\\nSpeaker A: I want to relax and maybe have a coffee before the film.\\nSpeaker B: Hi, Alex! I am free on Saturday. Maybe we can go to the cinema.\\nSpeaker B: Good idea. There is a café near the cinema.\\nSpeaker A: That sounds good. Which film do you want to see?\\nSpeaker A: We can have coffee at 3 pm then go to the cinema.\\nSpeaker B: I heard the new comedy \\\"Sunny Days\\\" is funny. It starts at 4 pm.\\nSpeaker A: OK, 4 pm works for me. How many tickets do we need?\\nSpeaker B: Just two tickets, one for each of us.\\nSpeaker A: Great. I will buy them online now.\\nSpeaker B: Perfect! Meet me at the mall at 3:30?\\nSpeaker A: Yes, see you then. Bye!\",\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What does Speaker A want to do before the film?\",\"options\":[\"Watch a trailer\",\"Have a coffee\",\"Play games\",\"Go shopping\"],\"correctAnswer\":\"Have a coffee\",\"explanation\":\"Trong đoạn hội thoại, Speaker A nói: \\\"I want to relax and maybe have a coffee before the film.\\\" Câu này rõ ràng chỉ muốn uống cà phê, vì vậy đáp án B là đúng. Các lựa chọn khác không xuất hiện trong đoạn.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"At what time does the film start?\",\"options\":[\"3 pm\",\"3:30 pm\",\"4 pm\",\"5 pm\"],\"correctAnswer\":\"4 pm\",\"explanation\":\"Speaker B nói: \\\"It starts at 4 pm.\\\" Đây là thời gian bắt đầu phim, nên đáp án C đúng. Các thời gian khác không được đề cập.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"How many tickets do they need?\",\"options\":[\"One\",\"Two\",\"Three\",\"Four\"],\"correctAnswer\":\"Two\",\"explanation\":\"Speaker B trả lời: \\\"Just two tickets, one for each of us.\\\" Điều này cho biết họ cần hai vé, vì vậy đáp án B là đúng.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Where will they meet before the film?\",\"options\":[\"At the cinema\",\"At the café\",\"At the mall\",\"At the park\"],\"correctAnswer\":\"At the mall\",\"explanation\":\"Speaker B đề xuất: \\\"Meet me at the mall at 3:30?\\\" Đây là địa điểm hẹn gặp, nên đáp án C là chính xác. Các địa điểm khác không được nêu.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Who will buy the tickets?\",\"options\":[\"Speaker A\",\"Speaker B\",\"Both\",\"No one\"],\"correctAnswer\":\"Speaker A\",\"explanation\":\"Speaker A nói: \\\"Great. I will buy them online now.\\\" Vì vậy, Speaker A sẽ mua vé, đáp án A là đúng.\"}],\"audioUrl\":\"https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/2cf55f33-3925-4ae0-a992-b6fed45dcf18.wav\",\"mediaUrl\":\"https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/2cf55f33-3925-4ae0-a992-b6fed45dcf18.wav\"}','READY_FOR_REVIEW'),(5,'2026-10-16 09:21:48.000000','2026-10-16 09:21:48.000000','A1','READING_FILL_BLANK','21c064eb-ae72-400d-9823-7c91f52fe9ac',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"readingPassage\":\"Anna lives in a quiet town. Every day she wakes up at 6:30 a.m. She brushes her teeth, eats a banana, and walks to the bus stop. On the bus Anna listens to her favourite pop songs. In the morning she also drinks a cup of tea before she starts work. At 7:15 a.m. she takes the bus to a small café near the centre. The café is called Green Leaf. Anna works there as a waitress. She serves coffee, tea, and fresh sandwiches to the customers. Her favourite drink to make is a cappuccino. During her break she helps clean the tables and talks with her colleagues. Anna\'s shift starts at 8:00 a.m. and ends at 4:00 p.m. After work she returns home, changes, and reads a book for an hour. In the evening she cooks dinner and goes to bed at 10:00 p.m.\",\"questions\":[{\"prompt\":\"Anna wakes up at ______.\",\"correctAnswer\":\"6:30 a.m.\",\"explanation\":\"\\\"She wakes up at 6:30 a.m.\\\" shows the exact time she gets up.\",\"questionType\":\"FILL_IN_BLANK\"},{\"prompt\":\"Anna works at a ______ café near the centre.\",\"correctAnswer\":\"small\",\"explanation\":\"The text says, \\\"she takes the bus to a small café near the centre.\\\"\",\"questionType\":\"FILL_IN_BLANK\"},{\"prompt\":\"Anna serves ______, tea, and sandwiches to the customers.\",\"correctAnswer\":\"coffee\",\"explanation\":\"\\\"She serves coffee, tea, and fresh sandwiches to the customers.\\\"\",\"questionType\":\"FILL_IN_BLANK\"},{\"prompt\":\"Anna finishes work at ______.\",\"correctAnswer\":\"4:00 p.m.\",\"explanation\":\"\\\"Anna\'s shift ... ends at 4:00 p.m.\\\" indicates her finishing time.\",\"questionType\":\"FILL_IN_BLANK\"},{\"prompt\":\"After work, Anna likes to ______ a book.\",\"correctAnswer\":\"read\",\"explanation\":\"\\\"After work she ... reads a book for an hour.\\\" provides the activity.\",\"questionType\":\"FILL_IN_BLANK\"}]}','READY_FOR_REVIEW'),(15,'2026-10-16 07:00:45.000000','2026-10-16 07:00:45.000000','B1','LISTENING_FILL','24bd2154-a8c5-456f-a6dc-420e441b2ed3',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"listeningPassage\":\"Good morning, ladies and gentlemen. This is a final announcement for Flight AB123 to Barcelona. The aircraft is a Boeing 737, scheduled to depart at 10:45 a.m. from Gate 22. However, due to a technical check on the rear landing gear, the departure has been delayed by fifteen minutes. Passengers who have already checked in may remain in the departure lounge while we complete the inspection. In addition, please note that the boarding gate has been changed to Gate 18. Boarding will now start at 10:30, ten minutes earlier than originally planned, to keep the new departure time on schedule. All passengers travelling with children are invited to use the family assistance desk located near Gate 18. If you need any assistance, the airline staff at counter 5 are ready to help. Remember to keep your boarding pass and identification ready for the gate agents. We apologise for any inconvenience and thank you for your patience. For further updates, please watch the monitors or listen to the next announcement. Due to the weather conditions over the Mediterranean, the airline has arranged an alternative route that will add approximately twenty minutes to the total flight time. Passengers are reminded that liquids in hand luggage must be stored in transparent bags and that electronic devices larger than a smartphone should be turned off during take‑off. The crew will also provide a complimentary beverage to all passengers after boarding is completed.\",\"questions\":[{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The announcement refers to Flight ______ to Barcelona.\",\"correctAnswer\":\"AB123\",\"explanation\":\"Trong đoạn nghe có câu: \\\"This is a final announcement for Flight AB123 to Barcelona.\\\" Vì vậy đáp án là AB123.\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The plane is scheduled to depart at ______ a.m.\",\"correctAnswer\":\"10:45\",\"explanation\":\"Câu trong đoạn: \\\"scheduled to depart at 10:45 a.m.\\\" cho biết thời gian khởi hành ban đầu.\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Originally the flight was to leave from ______.\",\"correctAnswer\":\"Gate 22\",\"explanation\":\"Đoạn nói: \\\"from Gate 22\\\" là cổng ban đầu của chuyến bay.\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Because of a technical check, the departure is delayed by ______ minutes.\",\"correctAnswer\":\"fifteen\",\"explanation\":\"Câu: \\\"the departure has been delayed by fifteen minutes\\\" chỉ thời gian trì hoãn.\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Boarding will now start at ______.\",\"correctAnswer\":\"10:30\",\"explanation\":\"Đoạn nghe: \\\"Boarding will now start at 10:30\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The boarding gate has been changed to ______.\",\"correctAnswer\":\"Gate 18\",\"explanation\":\"Câu: \\\"the boarding gate has been changed to Gate 18\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Passengers travelling with children should go to the family assistance desk near ______.\",\"correctAnswer\":\"Gate 18\",\"explanation\":\"Trong đoạn: \\\"family assistance desk located near Gate 18\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"If you need help, you can find airline staff at counter ______.\",\"correctAnswer\":\"5\",\"explanation\":\"Câu: \\\"the airline staff at counter 5 are ready to help\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Due to weather, the airline added about ______ minutes to the total flight time.\",\"correctAnswer\":\"twenty\",\"explanation\":\"Đoạn: \\\"add approximately twenty minutes to the total flight time\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Liquids in hand luggage must be stored in ______ bags.\",\"correctAnswer\":\"transparent\",\"explanation\":\"Câu: \\\"must be stored in transparent bags\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Electronic devices larger than a smartphone must be turned ______ during take‑off.\",\"correctAnswer\":\"off\",\"explanation\":\"Trong đoạn: \\\"should be turned off during take‑off\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The crew will provide a complimentary ______ after boarding is completed.\",\"correctAnswer\":\"beverage\",\"explanation\":\"Câu: \\\"provide a complimentary beverage to all passengers after boarding is completed\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The delay was caused by a technical check on the rear ______ gear.\",\"correctAnswer\":\"landing\",\"explanation\":\"Đoạn: \\\"technical check on the rear landing gear\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"The airline apologises for any ______.\",\"correctAnswer\":\"inconvenience\",\"explanation\":\"Câu: \\\"We apologise for any inconvenience\\\".\"},{\"questionType\":\"FILL_IN_BLANK\",\"prompt\":\"Passengers are asked to keep their boarding pass and ______ ready for the gate agents.\",\"correctAnswer\":\"identification\",\"explanation\":\"Trong đoạn: \\\"keep your boarding pass and identification ready\\\".\"}]}','READY_FOR_REVIEW'),(5,'2026-10-16 11:36:17.000000','2026-10-16 11:36:17.000000','A1','VOCAB_MEANING_TO_WORD','27076db1-166f-4a4b-99fc-4cd9b5947bfc',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"questions\":[{\"questionType\":\"FILL_IN_BLANK\",\"targetWord\":\"mother\",\"ipa\":\"/ˈmʌðər/\",\"prompt\":\"Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: m______):\\nA female parent: ______\",\"correctAnswer\":\"mother\",\"explanation\":\"Phiên âm IPA: /ˈmʌðər/ | Từ vựng: mother (noun) - mẹ.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\"},{\"questionType\":\"FILL_IN_BLANK\",\"targetWord\":\"brother\",\"ipa\":\"/ˈbrʌðər/\",\"prompt\":\"Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: b______):\\nA male sibling: ______\",\"correctAnswer\":\"brother\",\"explanation\":\"Phiên âm IPA: /ˈbrʌðər/ | Từ vựng: brother (noun) - anh trai hoặc em trai.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=brother&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=brother&type=2\"},{\"questionType\":\"FILL_IN_BLANK\",\"targetWord\":\"kitchen\",\"ipa\":\"/ˈkɪtʃɪn/\",\"prompt\":\"Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: k______):\\nThe room where you cook food: ______\",\"correctAnswer\":\"kitchen\",\"explanation\":\"Phiên âm IPA: /ˈkɪtʃɪn/ | Từ vựng: kitchen (noun) - bếp, nhà bếp.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\"},{\"questionType\":\"FILL_IN_BLANK\",\"targetWord\":\"breakfast\",\"ipa\":\"/ˈbrɛkfəst/\",\"prompt\":\"Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: b______):\\nThe first meal of the day, eaten in the morning: ______\",\"correctAnswer\":\"breakfast\",\"explanation\":\"Phiên âm IPA: /ˈbrɛkfəst/ | Từ vựng: breakfast (noun) - bữa sáng.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\"},{\"questionType\":\"FILL_IN_BLANK\",\"targetWord\":\"sofa\",\"ipa\":\"/ˈsəʊfə/\",\"prompt\":\"Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: s____):\\nA comfortable seat for several people in the living room: ______\",\"correctAnswer\":\"sofa\",\"explanation\":\"Phiên âm IPA: /ˈsəʊfə/ | Từ vựng: sofa (noun) - ghế sofa.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=sofa&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=sofa&type=2\"}]}','READY_FOR_REVIEW'),(5,'2026-10-15 19:02:59.000000','2026-10-15 19:02:59.000000','A1','SPEAKING_SHADOWING','2b759647-1338-41e6-8437-7ef6509b8856',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\n  \"questions\": [\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"I’m going to the park.\",\n      \"prompt\": \"I’m going to the park.\",\n      \"explanation\": \"Tôi đang đi tới công viên. / /aɪm ˈɡoʊɪŋ tə ðə pɑːrk/ – chú ý liên âm: “going to” thường được nói nhanh thành /ˈɡɒnə/. Nhấn mạnh từ “going” và “park”.\",\n      \"correctAnswer\": \"I’m going to the park.\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"Do you want some water?\",\n      \"prompt\": \"Do you want some water?\",\n      \"explanation\": \"Bạn có muốn một ít nước không? / /duː jʊ wɒnt sʌm ˈwɔːtə/ – liên âm: “Do you” → /duːjʊ/, “want some” → /wɒnt sʌm/. Nhấn mạnh từ “want” và “water”.\",\n      \"correctAnswer\": \"Do you want some water?\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"She’s coming from school.\",\n      \"prompt\": \"She’s coming from school.\",\n      \"explanation\": \"Cô ấy đang đến từ trường. / /ʃiːz ˈkʌmɪŋ frəm skuːl/ – liên âm: “She’s coming” → /ʃiːz ˈkʌmɪŋ/, “from school” → /frəm skuːl/. Nhấn mạnh “coming” và “school”.\",\n      \"correctAnswer\": \"She’s coming from school.\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"We have two apples.\",\n      \"prompt\": \"We have two apples.\",\n      \"explanation\": \"Chúng tôi có hai quả táo. / /wiː hæv tuː ˈæpəlz/ – liên âm: “We have” → /wiː hæv/, “two apples” → /tuː ˈæpəlz/. Nhấn mạnh “two” và “apples”.\",\n      \"correctAnswer\": \"We have two apples.\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"It’s nice to see you.\",\n      \"prompt\": \"It’s nice to see you.\",\n      \"explanation\": \"Thật vui khi gặp lại bạn. / /ɪts naɪs tə siː jʊ/ – liên âm: “It’s nice” → /ɪts naɪs/, “to see” → /tə siː/. Nhấn mạnh “nice” và “see”.\",\n      \"correctAnswer\": \"It’s nice to see you.\"\n    }\n  ]\n}','READY_FOR_REVIEW'),(5,'2026-10-16 10:01:02.000000','2026-10-16 10:01:02.000000','A1','GRAMMAR_VERB_CONJUGATION','339b3f4e-507d-4404-912d-86beaa2a9e24',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\n  \"questions\": [\n    {\n      \"prompt\": \"Dr. Lin (study) ______ coral reefs every summer as part of her marine biology research.\",\n      \"correctAnswer\": \"studies\",\n      \"explanation\": \"Công thức: Ngôi thứ ba số ít + động từ thêm -s/-es. Chủ ngữ \'Dr. Lin\' là ngôi thứ ba số ít, vì đây là thói quen nên dùng Present Simple. Động từ gốc \'study\' thêm -s → \'studies\'.\",\n      \"questionType\": \"FILL_IN_BLANK\"\n    },\n    {\n      \"prompt\": \"The sun (rise) ______ in the east, providing daylight for the whole planet.\",\n      \"correctAnswer\": \"rises\",\n      \"explanation\": \"Đây là một chân lý chung. Với ngôi thứ ba số ít \'the sun\', động từ ở dạng hiện tại đơn cần thêm -s. Vì \'rise\' kết thúc bằng âm e, chỉ cần thêm -s → \'rises\'.\",\n      \"questionType\": \"FILL_IN_BLANK\"\n    },\n    {\n      \"prompt\": \"My robot assistant (not charge) ______ its battery overnight.\",\n      \"correctAnswer\": \"doesn\'t charge\",\n      \"explanation\": \"Câu phủ định cho ngôi thứ ba số ít dùng trợ động từ \'does not\' (rút gọn thành doesn\'t) + động từ nguyên mẫu. Vì chủ ngữ \'my robot assistant\' là thứ ba số ít, nên dùng \'doesn\'t\' + \'charge\'.\",\n      \"questionType\": \"FILL_IN_BLANK\"\n    },\n    {\n      \"prompt\": \"Does the telescope (capture) ______ crystal‑clear images of distant galaxies every night?\",\n      \"correctAnswer\": \"capture\",\n      \"explanation\": \"Trong câu hỏi dạng Yes/No với Present Simple, trợ động từ \'does\' đã được dùng cho ngôi thứ ba số ít, vì vậy động từ sau ngoặc phải ở dạng nguyên mẫu không thêm -s. Do đó đáp án là \'capture\'.\",\n      \"questionType\": \"FILL_IN_BLANK\"\n    },\n    {\n      \"prompt\": \"She (have) ______ a coffee before starting her coding session each morning.\",\n      \"correctAnswer\": \"has\",\n      \"explanation\": \"Động từ bất quy tắc \'have\' ở ngôi thứ ba số ít thêm -s thành \'has\'. Đây là thói quen hằng ngày, vì vậy dùng Present Simple: \'She has a coffee...\'.\",\n      \"questionType\": \"FILL_IN_BLANK\"\n    }\n  ]\n}','READY_FOR_REVIEW'),(5,'2026-10-16 09:36:04.000000','2026-10-16 09:36:04.000000','A1','VOCAB_MATCHING','41503881-489d-4026-9388-cd895359aeed',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"mother\",\"ipa\":\"/ˈmʌðər/\",\"prompt\":\"Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'mother\' là gì?\",\"options\":[\"a female parent\",\"a place where you sleep\",\"a type of food\",\"a piece of furniture\"],\"correctAnswer\":\"a female parent\",\"explanation\":\"Phiên âm IPA: /ˈmʌðər/ | \'mother\' (noun): danh từ chỉ người phụ nữ sinh ra hoặc nuôi dưỡng con cái. Thường dùng trong ngữ cảnh gia đình: \\\"My mother cooks dinner every night.\\\"\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"kitchen\",\"ipa\":\"/ˈkɪtʃən/\",\"prompt\":\"Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'kitchen\' là gì?\",\"options\":[\"the room where you cook meals\",\"a type of clothing\",\"a vehicle for transporting goods\",\"a musical instrument\"],\"correctAnswer\":\"the room where you cook meals\",\"explanation\":\"Phiên âm IPA: /ˈkɪtʃən/ | \'kitchen\' (noun): danh từ chỉ phòng trong nhà dùng để nấu ăn và chuẩn bị thực phẩm. Ví dụ: \\\"The kitchen is clean and bright.\\\"\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"brush\",\"ipa\":\"/brʌʃ/\",\"prompt\":\"Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'brush\' là gì?\",\"options\":[\"a tool with bristles used for cleaning or painting\",\"a type of fruit\",\"a piece of clothing\",\"a musical genre\"],\"correctAnswer\":\"a tool with bristles used for cleaning or painting\",\"explanation\":\"Phiên âm IPA: /brʌʃ/ | \'brush\' (noun): dụng cụ có lông hoặc sợi dùng để chải, quét hoặc vẽ. Thường gặp trong câu: \\\"She uses a toothbrush to clean her teeth.\\\"\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=brush&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=brush&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"bed\",\"ipa\":\"/bɛd/\",\"prompt\":\"Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'bed\' là gì?\",\"options\":[\"a piece of furniture for sleeping\",\"a type of drink\",\"a kind of shoe\",\"a musical genre\"],\"correctAnswer\":\"a piece of furniture for sleeping\",\"explanation\":\"Phiên âm IPA: /bɛd/ | \'bed\' (noun): đồ nội thất dùng để nằm ngủ. Ví dụ: \\\"I made my bed after waking up.\\\"\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=bed&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=bed&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"breakfast\",\"ipa\":\"/ˈbrɛkfəst/\",\"prompt\":\"Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'breakfast\' là gì?\",\"options\":[\"the first meal of the day\",\"a type of exercise\",\"a bedtime story\",\"a holiday\"],\"correctAnswer\":\"the first meal of the day\",\"explanation\":\"Phiên âm IPA: /ˈbrɛkfəst/ | \'breakfast\' (noun): bữa ăn đầu tiên trong ngày, thường ăn vào buổi sáng. Ví dụ: \\\"We eat cereal for breakfast.\\\"\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\"}]}','READY_FOR_REVIEW'),(5,'2026-10-15 19:02:36.000000','2026-10-15 19:02:36.000000','A1','SPEAKING_SHADOWING','43bc6772-2bb7-41a8-ac00-0d274abfb4d9',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\n  \"questions\": [\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"Can I have a cup of tea?\",\n      \"prompt\": \"Can I have a cup of tea?\",\n      \"explanation\": \"Bạn có thể uống một tách trà không? – Lưu ý nối âm: \\\"Can I\\\" phát âm /kæn aɪ/ → /kænaɪ/; \\\"have a\\\" thành /hæv ə/ → /hævə/; \\\"a cup of\\\" nối thành /ə kʌp əv/. Trọng âm chính ở từ \\\"tea\\\".\",\n      \"correctAnswer\": \"Can I have a cup of tea?\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"I’m going to the market.\",\n      \"prompt\": \"I’m going to the market.\",\n      \"explanation\": \"Tôi sẽ đi đến chợ. – Nối âm: \\\"I’m\\\" /aɪm/; \\\"going to\\\" thường rút gọn thành /ˈɡoʊɪnə/ (âm /t/ bị bỏ); \\\"the\\\" /ðə/ nối liền với \\\"market\\\" /ˈmɑːrkɪt/. Trọng âm ở từ \\\"market\\\".\",\n      \"correctAnswer\": \"I’m going to the market.\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"Do you want some water?\",\n      \"prompt\": \"Do you want some water?\",\n      \"explanation\": \"Bạn có muốn một ít nước không? – Nối âm: \\\"Do you\\\" /du ju/ thường nghe như /dəʒu/; \\\"want some\\\" /wɒnt sʌm/ nối liền; \\\"some water\\\" /sʌm ˈwɔːtər/ với /m/ và /w/ liền nhau. Trọng âm ở từ \\\"water\\\".\",\n      \"correctAnswer\": \"Do you want some water?\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"She lives near the park.\",\n      \"prompt\": \"She lives near the park.\",\n      \"explanation\": \"Cô ấy sống gần công viên. – Nối âm: \\\"She lives\\\" /ʃi lɪvz/ liền nhau; \\\"near the\\\" /nɪr ðə/ → /nɪrðə/; \\\"the park\\\" /ðə pɑːrk/ nối mượt. Trọng âm ở từ \\\"park\\\".\",\n      \"correctAnswer\": \"She lives near the park.\"\n    },\n    {\n      \"questionType\": \"AUDIO_RESPONSE\",\n      \"question\": \"We can meet at five o’clock.\",\n      \"prompt\": \"We can meet at five o’clock.\",\n      \"explanation\": \"Chúng ta có thể gặp lúc năm giờ. – Nối âm: \\\"We can\\\" /wi kæn/ thường giảm thành /wi kən/; \\\"meet at\\\" /miːt æt/ liền; \\\"five o’clock\\\" /faɪv ə ˈklɒk/ với /v/ và /ə/ nối mượt. Trọng âm ở từ \\\"five\\\" và \\\"o’clock\\\".\",\n      \"correctAnswer\": \"We can meet at five o’clock.\"\n    }\n  ]\n}','READY_FOR_REVIEW'),(5,'2026-10-16 11:17:33.000000','2026-10-16 11:17:33.000000','A1','VOCAB_LISTEN_CHOOSE','54b5cd56-9ca6-469a-ad63-e816609fd5be',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"breakfast\",\"ipa\":\"/ˈbrɛkfəst/\",\"prompt\":\"[LISTEN_WORD] Nghe phát âm và chọn từ tiếng Anh chính xác bạn nghe được.\",\"options\":[\"breakfast\",\"breakfasts\",\"breakfasted\",\"breakfasting\"],\"correctAnswer\":\"breakfast\",\"explanation\":\"Phiên âm IPA: /ˈbrɛkfəst/, nghĩa: bữa sáng. Từ này dùng để chỉ bữa ăn đầu tiên trong ngày.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=breakfast&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"kitchen\",\"ipa\":\"/ˈkɪtʃən/\",\"prompt\":\"[LISTEN_WORD] Nghe phát âm và chọn từ tiếng Anh chính xác bạn nghe được.\",\"options\":[\"kitchen\",\"kittens\",\"kitchenware\",\"kitchenette\"],\"correctAnswer\":\"kitchen\",\"explanation\":\"Phiên âm IPA: /ˈkɪtʃən/, nghĩa: nhà bếp. Nơi chuẩn bị và nấu ăn.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=kitchen&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"mother\",\"ipa\":\"/ˈmʌðər/\",\"prompt\":\"[LISTEN_WORD] Nghe phát âm và chọn từ tiếng Anh chính xác bạn nghe được.\",\"options\":[\"mother\",\"other\",\"moth\",\"mothers\"],\"correctAnswer\":\"mother\",\"explanation\":\"Phiên âm IPA: /ˈmʌðər/, nghĩa: mẹ. Thành viên nữ trong gia đình, cha mẹ.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=mother&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"bed\",\"ipa\":\"/bɛd/\",\"prompt\":\"[LISTEN_WORD] Nghe phát âm và chọn từ tiếng Anh chính xác bạn nghe được.\",\"options\":[\"bed\",\"bad\",\"bet\",\"bid\"],\"correctAnswer\":\"bed\",\"explanation\":\"Phiên âm IPA: /bɛd/, nghĩa: giường. Đồ dùng để ngủ.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=bed&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=bed&type=2\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"targetWord\":\"chair\",\"ipa\":\"/tʃɛər/\",\"prompt\":\"[LISTEN_WORD] Nghe phát âm và chọn từ tiếng Anh chính xác bạn nghe được.\",\"options\":[\"chair\",\"share\",\"cheer\",\"char\"],\"correctAnswer\":\"chair\",\"explanation\":\"Phiên âm IPA: /tʃɛər/, nghĩa: ghế. Đồ nội thất dùng để ngồi.\",\"audioUrl\":\"https://dict.youdao.com/dictvoice?audio=chair&type=2\",\"mediaUrl\":\"https://dict.youdao.com/dictvoice?audio=chair&type=2\"}]}','READY_FOR_REVIEW'),(15,'2026-10-16 07:01:32.000000','2026-10-16 07:01:32.000000','B1','LISTENING_DIALOGUE','56bfab47-4adf-4ef9-a622-c635af301c26',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"listeningPassage\":\"Speaker A: Hey Maya, any weekend plans?\\nSpeaker B: Not yet, Tom. I’m eyeing the new sci‑fi film but I don’t know the showtimes.\\nSpeaker A: Main Street cinema has it at 3 pm on Saturday and 7 pm on Sunday, and they announced a 20 % student discount yesterday. Because the cinema expects high demand, they opened an extra screening for the weekend.\\nSpeaker B: I work a shift Saturday morning, finishing at 12 pm, and I have a meeting with my boss at 2 pm on Sunday. I usually commute by bike, but yesterday I missed the bus and had to walk.\\nSpeaker A: If you pick the 7 pm Sunday showing you’ll still have time after the meeting.\\nSpeaker B: The earlier 3 pm slot would let us have coffee first; there’s a new café near the cinema that serves oat milk lattes and keeps prices low because they source beans locally. Since the coffee is cheap, many students stop there before movies.\\nSpeaker A: Should we book online? Seats fill up fast, especially for 3 pm.\\nSpeaker B: Yes, book two tickets for 3 pm and text me the confirmation.\\nSpeaker A: Wait, the 3 pm show clashes with my friend’s birthday brunch at 1 pm Saturday.\\nSpeaker B: Then let’s go to the Sunday evening screening.\\nSpeaker A: Agreed. I’ll buy Sunday 7 pm tickets and collect them at the box office tomorrow.\\nSpeaker B: Great, I’ll meet you at the café around 6 pm before the film.\",\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What percentage discount was announced for students?\",\"options\":[\"A) 10%\",\"B) 15%\",\"C) 20%\",\"D) 25%\"],\"correctAnswer\":\"C) 20%\",\"explanation\":\"Trong đoạn hội thoại, Speaker A nói: \\\"they announced a 20 % student discount yesterday\\\". Vì vậy đáp án đúng là 20%.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Where is the cinema located?\",\"options\":[\"A) Oak Avenue\",\"B) Main Street\",\"C) River Plaza\",\"D) Central Mall\"],\"correctAnswer\":\"B) Main Street\",\"explanation\":\"Speaker A đề cập tới \\\"Main Street cinema\\\". Các lựa chọn khác không xuất hiện trong đoạn, nên đúng là Main Street.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"At what time is the Saturday showing?\",\"options\":[\"A) 2 pm\",\"B) 3 pm\",\"C) 4 pm\",\"D) 5 pm\"],\"correctAnswer\":\"B) 3 pm\",\"explanation\":\"Câu \\\"has it at 3 pm on Saturday\\\" cho biết giờ chiếu vào thứ Bảy là 3 pm.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Why did the cinema open an extra screening?\",\"options\":[\"A) Because they had a technical issue\",\"B) Because they expect high demand\",\"C) Because a celebrity visited\",\"D) Because of a holiday\"],\"correctAnswer\":\"B) Because they expect high demand\",\"explanation\":\"Sau khi thông báo giảm giá, Speaker A nói: \\\"Because the cinema expects high demand, they opened an extra screening\\\". Do đó đáp án B là đúng.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What time does Speaker B finish his Saturday shift?\",\"options\":[\"A) 10 am\",\"B) 11 am\",\"C) 12 pm\",\"D) 1 pm\"],\"correctAnswer\":\"C) 12 pm\",\"explanation\":\"Speaker B nói: \\\"finishing at 12 pm\\\". Vì vậy đáp án là 12 pm.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"When is Speaker B\'s meeting with his boss?\",\"options\":[\"A) 12 pm\",\"B) 1 pm\",\"C) 2 pm\",\"D) 3 pm\"],\"correctAnswer\":\"C) 2 pm\",\"explanation\":\"Trong câu \\\"I have a meeting with my boss at 2 pm on Sunday\\\" thời gian gặp là 2 pm.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What caused Speaker B to walk instead of bike?\",\"options\":[\"A) He prefers walking\",\"B) He missed the bus\",\"C) His bike broke\",\"D) He was late for work\"],\"correctAnswer\":\"B) He missed the bus\",\"explanation\":\"Speaker B nói: \\\"but yesterday I missed the bus and had to walk\\\". Do đó đáp án B là đúng.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What does the new café near the cinema serve?\",\"options\":[\"A) Espresso\",\"B) oat milk lattes\",\"C) smoothies\",\"D) tea\"],\"correctAnswer\":\"B) oat milk lattes\",\"explanation\":\"Câu \\\"there’s a new café … that serves oat milk lattes\\\" chỉ ra loại đồ uống được phục vụ.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Why are the café prices described as cheap?\",\"options\":[\"A) Because they source beans locally\",\"B) Because they have a discount\",\"C) Because they use instant coffee\",\"D) Because they are a chain\"],\"correctAnswer\":\"A) Because they source beans locally\",\"explanation\":\"Speaker B giải thích: \\\"keeps prices low because they source beans locally\\\". Vì vậy đáp án A là đúng.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What reason does Speaker B give for choosing the earlier show?\",\"options\":[\"A) To avoid traffic\",\"B) To have coffee first\",\"C) To finish work early\",\"D) To meet a friend\"],\"correctAnswer\":\"B) To have coffee first\",\"explanation\":\"Speaker B nói: \\\"The earlier 3 pm slot would let us have coffee first\\\". Do đó đáp án B.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"How does Speaker A suggest booking tickets?\",\"options\":[\"A) By phone\",\"B) Online\",\"C) At the box office\",\"D) Through a travel agency\"],\"correctAnswer\":\"B) Online\",\"explanation\":\"Speaker A hỏi: \\\"Should we book online?\\\" Đây là đề xuất đặt vé trực tuyến.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"How will Speaker A send the ticket confirmation?\",\"options\":[\"A) Email\",\"B) Text message\",\"C) WhatsApp\",\"D) Postal mail\"],\"correctAnswer\":\"B) Text message\",\"explanation\":\"Speaker B trả lời: \\\"text me the confirmation\\\". Vì vậy cách gửi là tin nhắn văn bản.\"}]}','READY_FOR_REVIEW'),(5,'2026-10-16 06:11:04.000000','2026-10-16 06:11:04.000000','A1','LISTENING_DIALOGUE','5a0f14e7-5f6c-42fc-9859-7523f04b36b0',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"listeningPassage\":\"Speaker A: Hi, Sara. Do you have any plans for this weekend?\\nSpeaker B: Hi, Tom. I don\'t have anything yet. What do you suggest?\\nSpeaker A: I was thinking of going to the new movie on Saturday afternoon. The film is called \\\"Sunny Beach\\\".\\nSpeaker B: That sounds good! What time does it start?\\nSpeaker A: It starts at 2 o\'clock. We can meet at the cinema at 1:45.\\nSpeaker B: Okay. How much is a ticket?\\nSpeaker A: One ticket is five euros. We can buy them online.\\nSpeaker B: Great! I will bring some popcorn and drinks.\\nSpeaker A: Perfect. See you Saturday at the cinema then.\\nSpeaker B: Do you want to get coffee after the film?\\nSpeaker A: Yes, there is a nice café near the cinema.\\nSpeaker B: Okay, I will meet you there at 4:30.\\nSpeaker A: See you!\",\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"On which day do the friends plan to go to the cinema?\",\"options\":[\"A) Friday\",\"B) Saturday\",\"C) Sunday\",\"D) Monday\"],\"correctAnswer\":\"B) Saturday\",\"explanation\":\"Trong đoạn hội thoại, Speaker A nói \\\"I was thinking of going to the new movie on Saturday afternoon.\\\" Vì vậy đáp án đúng là \\\"Saturday\\\" (B). Các lựa chọn khác không xuất hiện trong đoạn.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What time does the movie start?\",\"options\":[\"A) 1 o\'clock\",\"B) 2 o\'clock\",\"C) 3 o\'clock\",\"D) 4 o\'clock\"],\"correctAnswer\":\"B) 2 o\'clock\",\"explanation\":\"Speaker A trả lời câu hỏi \\\"What time does it start?\\\" bằng câu \\\"It starts at 2 o\'clock.\\\" Do đó đáp án đúng là 2 o\'clock (B). Các thời gian khác không được đề cập.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"How much is one cinema ticket?\",\"options\":[\"A) three euros\",\"B) four euros\",\"C) five euros\",\"D) six euros\"],\"correctAnswer\":\"C) five euros\",\"explanation\":\"Speaker A nói \\\"One ticket is five euros.\\\" Đây là thông tin duy nhất về giá vé, nên đáp án đúng là \\\"five euros\\\" (C). Các mức giá khác là bẫy.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What do the friends plan to do after the film?\",\"options\":[\"A) Go shopping\",\"B) Get coffee\",\"C) Visit a museum\",\"D) Play video games\"],\"correctAnswer\":\"B) Get coffee\",\"explanation\":\"Speaker B hỏi \\\"Do you want to get coffee after the film?\\\" và Speaker A đồng ý. Vì vậy hành động sau phim là \\\"get coffee\\\" (B). Các hoạt động khác không xuất hiện.\"},{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"Where will they meet for coffee?\",\"options\":[\"A) At the cinema lobby\",\"B) At a restaurant nearby\",\"C) At a nice café near the cinema\",\"D) At Speaker B\'s house\"],\"correctAnswer\":\"C) At a nice café near the cinema\",\"explanation\":\"Speaker A trả lời \\\"Yes, there is a nice café near the cinema.\\\" Đây là địa điểm họ sẽ gặp nhau để uống cà phê, nên đáp án C là đúng. Các địa điểm khác không được nhắc tới.\"}],\"audioUrl\":\"https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/c16fe0ed-79a4-4497-9790-34dc867076b1.wav\",\"mediaUrl\":\"https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/c16fe0ed-79a4-4497-9790-34dc867076b1.wav\"}','READY_FOR_REVIEW'),(5,'2026-10-16 07:30:04.000000','2026-10-16 07:30:04.000000','A1','LISTENING_DIALOGUE','6f6a8307-f92b-4907-bcb2-a518175a5f14',NULL,'831551b0-25ef-46f8-a834-eb1945a5aad0','{\"listeningPassage\":\"Speaker A: Hi, Lisa! Do you have any plans for the weekend?\\nSpeaker B: Hi, Tom! I want to go to the cinema on Saturday.\\nSpeaker A: Which film do you want to see?\\nSpeaker B: I want to see the new comedy, \\\"Funny Day\\\".\\nSpeaker A: That sounds good. The cinema is at 3 pm. Can we buy tickets now?\\nSpeaker B: Yes, we can buy two tickets online.\\nSpeaker A: Great! I will pay with my card.\\nSpeaker A: Do you want popcorn and drinks?\\nSpeaker B: Yes, please. One small popcorn and a cola.\\nSpeaker A: OK, I will meet you at the cinema entrance at 2:45.\\nSpeaker B: See you then. Bye!\\nSpeaker A: Bye!\",\"questions\":[{\"questionType\":\"MULTIPLE_CHOICE\",\"prompt\":\"What does Speaker B want 