INSERT INTO `assignment_questions` VALUES (1,20,'d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','04f82b2a-31be-4a81-93a9-eb9fe90fae0f',NULL,'interactive','Từ vựng \'interactive\' (tính từ) nghĩa là có tính tương tác cao.','Đọc ngữ cảnh: \'Digital platforms enable interactive learning environments where students actively engage with multimedia content.\'\nĐiền từ còn thiếu vào câu sau:\nDigital platforms enable __________ learning environments where students actively engage with multimedia content.',NULL,'FILL_IN_BLANK'),(3,1,'da5fc9fd-afd1-4298-bb9d-c6e4b7395986','0522199c-88f9-403c-9cd8-9715a0d8cd4f','https://dict.youdao.com/dictvoice?audio=brush&type=2','a tool with bristles used for cleaning or painting','Phiên âm IPA: /brʌʃ/ | \'brush\' (noun): dụng cụ có lông hoặc sợi dùng để chải, quét hoặc vẽ. Thường gặp trong câu: \"She uses a toothbrush to clean her teeth.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'brush\' là gì?',NULL,'MULTIPLE_CHOICE'),(5,1,'a7bb938c-486a-4b2e-9544-b27b1cac49d8','05a76ab9-d1b4-4700-a1a8-3e847577bcf1',NULL,'has','Động từ bất quy tắc \'have\' ở ngôi thứ ba số ít thêm -s thành \'has\'. Đây là thói quen hằng ngày, vì vậy dùng Present Simple: \'She has a coffee...\'.','She (have) ______ a coffee before starting her coding session each morning.',NULL,'FILL_IN_BLANK'),(4,20,'d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','0fb3f7a8-bc23-4141-a4b0-a07fb4c71eee',NULL,'digital','Từ \'digital\' (tính từ) thuộc về kỹ thuật số.','Đọc ngữ cảnh: \'The integration of modern digital devices prepares learners for the demands of the future.\'\nĐiền từ còn thiếu vào câu sau:\nThe integration of modern __________ devices transforms traditional educational methods.',NULL,'FILL_IN_BLANK'),(1,1,'bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15','1058d449-56d6-4935-a1db-60ecb7e71a42','https://dict.youdao.com/dictvoice?audio=mother&type=2','a female parent','Phiên âm IPA: /ˈmʌðər/ | \'mother\' (noun): người mẹ, là phụ huynh nữ. Dùng để nói về người phụ trách nuôi dạy con cái. Ví dụ: My mother cooks dinner every night.','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'mother\' là gì?',NULL,'MULTIPLE_CHOICE'),(4,1,'9b6dfda3-0798-459d-b9e0-b8d98ea66f6c','1623f986-24cc-4280-b769-63d85da00b94',NULL,'4:00 p.m.','\"Anna\'s shift ... ends at 4:00 p.m.\" indicates her finishing time.','Anna finishes work at ______.',NULL,'FILL_IN_BLANK'),(4,1,'bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15','194ca2ef-e182-46e3-bbc6-3c55951cf9d3','https://dict.youdao.com/dictvoice?audio=breakfast&type=2','the first meal of the day','Phiên âm IPA: /ˈbrɛkfəst/ | \'breakfast\' (noun): bữa sáng, bữa ăn đầu tiên sau khi ngủ. Ví dụ: I eat cereal for breakfast.','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'breakfast\' là gì?',NULL,'MULTIPLE_CHOICE'),(2,20,'d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','1c965a83-401d-40a7-ae40-c132c43a1e34',NULL,'accessible','Từ \'accessible\' (tính từ) nghĩa là dễ dàng tiếp cận, mở rộng cơ hội cho mọi người.','Đọc ngữ cảnh: \'Online collaboration tools have made teamwork more accessible, breaking down geographic barriers for global classrooms.\'\nĐiền từ còn thiếu vào câu sau:\nOnline collaboration tools have made teamwork more __________ across geographical distances.',NULL,'FILL_IN_BLANK'),(3,1,'bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15','2525fdcb-8845-4af1-9a85-e3f2e8ea49a8','https://dict.youdao.com/dictvoice?audio=kitchen&type=2','a room where food is prepared','Phiên âm IPA: /ˈkɪtʃən/ | \'kitchen\' (noun): nhà bếp, nơi nấu ăn và chuẩn bị thực phẩm. Ví dụ: The kitchen is clean today.','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'kitchen\' là gì?',NULL,'MULTIPLE_CHOICE'),(2,20,'37d53305-5705-458f-ada0-60fee4318321','26706e35-25bc-4356-8b3a-c97b574d7458',NULL,'released','Mốc thời gian xác định \'In 1991\' chỉ sự kiện lịch sử đã chấm dứt hoàn toàn trong quá khứ nên dùng Quá khứ đơn (released).','In 1991, British computer scientist Tim Berners-Lee __________ the World Wide Web to the public for the first time.',NULL,'MULTIPLE_CHOICE'),(2,1,'fba24678-3eed-47a4-8022-14761e73033e','315301c2-e9e4-4c68-ae3c-25ee6ab8ab5c','https://dict.youdao.com/dictvoice?audio=brother&type=2','brother','Phiên âm IPA: /ˈbrʌðər/ | Từ vựng: brother (noun) - anh trai hoặc em trai.','Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: b______):\nA male sibling: ______',NULL,'FILL_IN_BLANK'),(5,20,'d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','40f8ca07-9870-4b99-89db-3db4778cd698',NULL,'demands','Từ \'demands\' (danh từ số nhiều) nghĩa là các yêu cầu, đòi hỏi của thị trường lao động.','Đọc ngữ cảnh: \'Ultimately, the adoption of educational technology prepares learners for competitive workplace demands.\'\nĐiền từ còn thiếu vào câu sau:\nAdopting educational technology prepares learners for competitive workplace __________.',NULL,'FILL_IN_BLANK'),(4,1,'a7bb938c-486a-4b2e-9544-b27b1cac49d8','4b73ae8e-073d-4f69-8f36-291e0dce10d8',NULL,'capture','Trong câu hỏi dạng Yes/No với Present Simple, trợ động từ \'does\' đã được dùng cho ngôi thứ ba số ít, vì vậy động từ sau ngoặc phải ở dạng nguyên mẫu không thêm -s. Do đó đáp án là \'capture\'.','Does the telescope (capture) ______ crystal‑clear images of distant galaxies every night?',NULL,'FILL_IN_BLANK'),(4,1,'fba24678-3eed-47a4-8022-14761e73033e','4cd3f752-0a08-45a4-a996-0baa3bad6e5a','https://dict.youdao.com/dictvoice?audio=breakfast&type=2','breakfast','Phiên âm IPA: /ˈbrɛkfəst/ | Từ vựng: breakfast (noun) - bữa sáng.','Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: b______):\nThe first meal of the day, eaten in the morning: ______',NULL,'FILL_IN_BLANK'),(1,1,'b1704c0d-0dc1-49e6-b0c7-1aa595c8f906','5e908673-5b3d-4c4f-978a-34a7893e85c5','https://dict.youdao.com/dictvoice?audio=mother&type=2','a female parent','Phiên âm IPA: /ˈmʌðər/ | \'mother\' (noun): danh từ chỉ người phụ nữ sinh ra hoặc nuôi dưỡng con cái. Thường dùng trong ngữ cảnh gia đình: \"My mother cooks dinner every night.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'mother\' là gì?',NULL,'MULTIPLE_CHOICE'),(3,1,'dcd05d71-9d3a-4ec1-8b0f-a19de5488187','638cad4b-9a6a-4152-bf97-91a931956e5c',NULL,'B) 3:00 pm','Speaker A nói: \"The cinema is at 3 pm.\" Điều này chỉ thời gian bắt đầu phim, nên đáp án B là đúng. Các thời gian khác không được nhắc tới.','At what time does the cinema start the film?',NULL,'MULTIPLE_CHOICE'),(4,1,'dcd05d71-9d3a-4ec1-8b0f-a19de5488187','67cb9ddf-ade8-42be-a2d0-af310e823500',NULL,'B) Two','Speaker B trả lời: \"Yes, we can buy two tickets online.\" Số lượng vé rõ ràng là hai, vì vậy đáp án B là chính xác.','How many tickets will they buy?',NULL,'MULTIPLE_CHOICE'),(5,1,'dcd05d71-9d3a-4ec1-8b0f-a19de5488187','6f5b1b0b-bfc2-4757-9d4e-39b04d0475da',NULL,'B) At the cinema entrance','Speaker A nói: \"I will meet you at the cinema entrance at 2:45.\" Đây là địa điểm hẹn, nên đáp án B là đúng. Các địa điểm khác không được đề cập.','Where will they meet before the film?',NULL,'MULTIPLE_CHOICE'),(2,1,'a7bb938c-486a-4b2e-9544-b27b1cac49d8','71c15a62-8456-4bbc-969d-b1230475b1a2',NULL,'rises','Đây là một chân lý chung. Với ngôi thứ ba số ít \'the sun\', động từ ở dạng hiện tại đơn cần thêm -s. Vì \'rise\' kết thúc bằng âm e, chỉ cần thêm -s → \'rises\'.','The sun (rise) ______ in the east, providing daylight for the whole planet.',NULL,'FILL_IN_BLANK'),(1,10,'2a4a0d9c-595a-499a-be62-6d440549c65f','721390d9-87b7-4b15-90ad-70dc8ea282e7',NULL,'','Giáo viên sẽ trực tiếp chấm điểm bài luận theo 4 tiêu chí chuẩn IELTS B1+.','Topic:\nSome people believe that online learning is more effective than traditional face-to-face classroom learning, while others argue that physical classrooms are irreplaceable.\n\nWrite an opinion essay (150 - 200 words) presenting your viewpoint. Give reasons for your answer and include any relevant examples from your knowledge or experience.\n\nAssessment Criteria:\n1. Task Response (Clear thesis statement & fully developed main ideas)\n2. Coherence and Cohesion (Logical paragraph structure and cohesive transition words)\n3. Lexical Resource (Academic vocabulary, collocations, correct word forms)\n4. Grammatical Range and Accuracy (Complex sentences, correct tense usage)',NULL,'ESSAY'),(3,1,'a7bb938c-486a-4b2e-9544-b27b1cac49d8','7c894a05-cead-4aef-ae12-51722735afe2',NULL,'doesn\'t charge','Câu phủ định cho ngôi thứ ba số ít dùng trợ động từ \'does not\' (rút gọn thành doesn\'t) + động từ nguyên mẫu. Vì chủ ngữ \'my robot assistant\' là thứ ba số ít, nên dùng \'doesn\'t\' + \'charge\'.','My robot assistant (not charge) ______ its battery overnight.',NULL,'FILL_IN_BLANK'),(1,1,'dcd05d71-9d3a-4ec1-8b0f-a19de5488187','805e056e-1984-4730-bc5a-20d87f46ac50','https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/2e6ee412-c5e8-4702-88e3-5b3e3fac6733.wav','B) Go to the cinema','Trong đoạn hội thoại, Speaker B nói: \"I want to go to the cinema on Saturday.\" Đây là câu trả lời trực tiếp, loại bỏ các lựa chọn A, C, D.','What does Speaker B want to do on Saturday?',NULL,'MULTIPLE_CHOICE'),(5,20,'37d53305-5705-458f-ada0-60fee4318321','914f548d-c6fd-46bb-bca0-4bdb6c3154bb',NULL,'implemented','Mệnh đề sau \'Ever since\' chỉ mốc thời gian bắt đầu trong quá khứ nên dùng Quá khứ đơn (implemented), mệnh đề chính dùng Hiện tại hoàn thành.','Ever since universities __________ hybrid learning systems, student participation has increased significantly.',NULL,'MULTIPLE_CHOICE'),(3,1,'fba24678-3eed-47a4-8022-14761e73033e','923442ca-1aae-468d-b209-72af85a2e343','https://dict.youdao.com/dictvoice?audio=kitchen&type=2','kitchen','Phiên âm IPA: /ˈkɪtʃɪn/ | Từ vựng: kitchen (noun) - bếp, nhà bếp.','Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: k______):\nThe room where you cook food: ______',NULL,'FILL_IN_BLANK'),(1,1,'9b6dfda3-0798-459d-b9e0-b8d98ea66f6c','9b545503-f3f2-4487-815d-2608d39731b7',NULL,'6:30 a.m.','\"She wakes up at 6:30 a.m.\" shows the exact time she gets up.','Anna wakes up at ______.',NULL,'FILL_IN_BLANK'),(5,1,'da5fc9fd-afd1-4298-bb9d-c6e4b7395986','9d168ce9-ade5-43b5-93af-46c3814e4032','https://dict.youdao.com/dictvoice?audio=breakfast&type=2','the first meal of the day','Phiên âm IPA: /ˈbrɛkfəst/ | \'breakfast\' (noun): bữa ăn đầu tiên trong ngày, thường ăn vào buổi sáng. Ví dụ: \"We eat cereal for breakfast.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'breakfast\' là gì?',NULL,'MULTIPLE_CHOICE'),(1,10,'fe7a5c29-c0b0-42ea-a065-ca8032ac9aff','9e510f37-aeda-4d66-beb4-1bc79a1a6a24','https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/ddad27b4-c3cd-4fe8-9c57-8764d4daa80d.wav','Speaking presentation response','Giáo viên và hệ thống AI sẽ đánh giá độ lưu loát, từ vựng và ngữ pháp của bài nói.','Speaking Q&A:\nDescribe a memorable learning experience that had a significant impact on your academic journey.\nYou should explain:\n- What you learned\n- Where and when it happened\n- Why it was memorable, and how it shaped your approach to studying.',NULL,'AUDIO_RESPONSE'),(1,1,'fba24678-3eed-47a4-8022-14761e73033e','9ede4f2b-0505-48c1-914f-5207008916b3','https://dict.youdao.com/dictvoice?audio=mother&type=2','mother','Phiên âm IPA: /ˈmʌðər/ | Từ vựng: mother (noun) - mẹ.','Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: m______):\nA female parent: ______',NULL,'FILL_IN_BLANK'),(2,1,'da5fc9fd-afd1-4298-bb9d-c6e4b7395986','9f1de233-91e3-40f9-bafa-5615aa077899','https://dict.youdao.com/dictvoice?audio=kitchen&type=2','the room where you cook meals','Phiên âm IPA: /ˈkɪtʃən/ | \'kitchen\' (noun): danh từ chỉ phòng trong nhà dùng để nấu ăn và chuẩn bị thực phẩm. Ví dụ: \"The kitchen is clean and bright.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'kitchen\' là gì?',NULL,'MULTIPLE_CHOICE'),(1,1,'a7bb938c-486a-4b2e-9544-b27b1cac49d8','aaa3a023-6f5a-4e0e-a7be-ab486dc71a28',NULL,'studies','Công thức: Ngôi thứ ba số ít + động từ thêm -s/-es. Chủ ngữ \'Dr. Lin\' là ngôi thứ ba số ít, vì đây là thói quen nên dùng Present Simple. Động từ gốc \'study\' thêm -s → \'studies\'.','Dr. Lin (study) ______ coral reefs every summer as part of her marine biology research.',NULL,'FILL_IN_BLANK'),(4,1,'da5fc9fd-afd1-4298-bb9d-c6e4b7395986','b35a0560-3b47-4802-8f6a-d8eb7285fe1c','https://dict.youdao.com/dictvoice?audio=bed&type=2','a piece of furniture for sleeping','Phiên âm IPA: /bɛd/ | \'bed\' (noun): đồ nội thất dùng để nằm ngủ. Ví dụ: \"I made my bed after waking up.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'bed\' là gì?',NULL,'MULTIPLE_CHOICE'),(1,1,'da5fc9fd-afd1-4298-bb9d-c6e4b7395986','c2a9e777-9f78-4112-9383-3f1a66613e94','https://dict.youdao.com/dictvoice?audio=mother&type=2','a female parent','Phiên âm IPA: /ˈmʌðər/ | \'mother\' (noun): danh từ chỉ người phụ nữ sinh ra hoặc nuôi dưỡng con cái. Thường dùng trong ngữ cảnh gia đình: \"My mother cooks dinner every night.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'mother\' là gì?',NULL,'MULTIPLE_CHOICE'),(2,1,'9b6dfda3-0798-459d-b9e0-b8d98ea66f6c','cc10d2d4-3a0d-44f5-ba99-e23fd8271bc4',NULL,'small','The text says, \"she takes the bus to a small café near the centre.\"','Anna works at a ______ café near the centre.',NULL,'FILL_IN_BLANK'),(3,20,'d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','cd4efdd6-6fb7-4c33-9e6f-d0b9efd176b7',NULL,'efficient','Từ \'efficient\' (tính từ) nghĩa là đạt hiệu suất, hiệu quả cao.','Đọc ngữ cảnh: \'Artificial intelligence helps educators design personalized study pathways, making classroom instruction significantly more efficient.\'\nĐiền từ còn thiếu vào câu sau:\nPersonalized study pathways make classroom instruction significantly more __________.',NULL,'FILL_IN_BLANK'),(1,20,'37d53305-5705-458f-ada0-60fee4318321','d074a0d3-108d-4c03-a3b1-b34cdfb70156',NULL,'have demonstrated','Chủ ngữ \'Recent studies\' là danh từ số nhiều, diễn tả phát hiện nghiên cứu còn giá trị đến hiện tại nên dùng thì Hiện tại hoàn thành (have demonstrated).','Recent studies in environmental science __________ a significant correlation between deforestation and local climate shifts.',NULL,'MULTIPLE_CHOICE'),(3,20,'37d53305-5705-458f-ada0-60fee4318321','d13f8b46-8940-4f95-bed5-62096707b577',NULL,'have investigated','Dấu hiệu \'for over a decade\' biểu thị hành động bắt đầu từ quá khứ và vẫn tiếp diễn đến hiện tại nên dùng Hiện tại hoàn thành (have investigated).','Cognitive psychologists __________ the impact of smartphone usage on human attention spans for over a decade.',NULL,'MULTIPLE_CHOICE'),(2,10,'fe7a5c29-c0b0-42ea-a065-ca8032ac9aff','d4c58c48-7ab6-4155-82b1-e8ebb18aeee3','https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/c99150c0-e7d5-448a-b65e-f9e9902d53a6.wav','Technological innovations have fundamentally reshaped modern pedagogical methodologies.','Luyện tập ngữ âm và trọng âm câu với các từ đa âm tiết: technological, fundamentally, pedagogical, methodologies.','Shadowing Practice 1:\nHãy nghe và lặp lại chính xác ngữ điệu câu sau:\n\'Technological innovations have fundamentally reshaped modern pedagogical methodologies.\'',NULL,'AUDIO_RESPONSE'),(5,1,'fba24678-3eed-47a4-8022-14761e73033e','d94d2d6a-f8d1-4ff4-97a3-f3582f0cc852','https://dict.youdao.com/dictvoice?audio=sofa&type=2','sofa','Phiên âm IPA: /ˈsəʊfə/ | Từ vựng: sofa (noun) - ghế sofa.','Đọc định nghĩa và nhập từ vựng tiếng Anh phù hợp (Gợi ý: s____):\nA comfortable seat for several people in the living room: ______',NULL,'FILL_IN_BLANK'),(5,1,'b1704c0d-0dc1-49e6-b0c7-1aa595c8f906','dc5cccb0-53f5-4f9c-9140-41976921e2c6','https://dict.youdao.com/dictvoice?audio=breakfast&type=2','the first meal of the day','Phiên âm IPA: /ˈbrɛkfəst/ | \'breakfast\' (noun): bữa ăn đầu tiên trong ngày, thường ăn vào buổi sáng. Ví dụ: \"We eat cereal for breakfast.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'breakfast\' là gì?',NULL,'MULTIPLE_CHOICE'),(5,1,'9b6dfda3-0798-459d-b9e0-b8d98ea66f6c','dc826dc3-6f37-4ea2-85c1-39b224ae2959',NULL,'read','\"After work she ... reads a book for an hour.\" provides the activity.','After work, Anna likes to ______ a book.',NULL,'FILL_IN_BLANK'),(3,1,'9b6dfda3-0798-459d-b9e0-b8d98ea66f6c','de8ae1ee-e5b7-49f2-98e8-97e452febc5e',NULL,'coffee','\"She serves coffee, tea, and fresh sandwiches to the customers.\"','Anna serves ______, tea, and sandwiches to the customers.',NULL,'FILL_IN_BLANK'),(4,1,'b1704c0d-0dc1-49e6-b0c7-1aa595c8f906','dfce8151-db8a-4b76-b555-7c21d4d73c27','https://dict.youdao.com/dictvoice?audio=bed&type=2','a piece of furniture for sleeping','Phiên âm IPA: /bɛd/ | \'bed\' (noun): đồ nội thất dùng để nằm ngủ. Ví dụ: \"I made my bed after waking up.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'bed\' là gì?',NULL,'MULTIPLE_CHOICE'),(3,10,'fe7a5c29-c0b0-42ea-a065-ca8032ac9aff','e51e38d3-c0bc-4ef6-bcdb-6d4a5eda5371','https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/371a20a8-5c3a-4d90-a55e-64799b9998d1.wav','Consistent pronunciation practice and phonemic awareness enhance oral fluency.','Chú ý nối âm giữa các phụ âm cuối và nguyên âm trong \'phonemic awareness\', \'enhance oral\'.','Shadowing Practice 2:\nHãy nghe và lặp lại chính xác ngữ điệu câu sau:\n\'Consistent pronunciation practice and phonemic awareness enhance oral fluency.\'',NULL,'AUDIO_RESPONSE'),(3,1,'b1704c0d-0dc1-49e6-b0c7-1aa595c8f906','e60aba70-e88d-407c-bf8b-de6a332398f6','https://dict.youdao.com/dictvoice?audio=brush&type=2','a tool with bristles used for cleaning or painting','Phiên âm IPA: /brʌʃ/ | \'brush\' (noun): dụng cụ có lông hoặc sợi dùng để chải, quét hoặc vẽ. Thường gặp trong câu: \"She uses a toothbrush to clean her teeth.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'brush\' là gì?',NULL,'MULTIPLE_CHOICE'),(2,1,'dcd05d71-9d3a-4ec1-8b0f-a19de5488187','e81c0d8d-33f3-4420-9a0a-7dd178a122ae',NULL,'A) Funny Day','Speaker B trả lời: \"I want to see the new comedy, \\\"Funny Day\\\".\" Vì vậy đáp án đúng là A. Các đáp án khác không xuất hiện trong đoạn hội thoại.','What is the name of the film they plan to watch?',NULL,'MULTIPLE_CHOICE'),(5,1,'bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15','e8d2a656-2d8b-4277-90b2-65bb2d6a92ef','https://dict.youdao.com/dictvoice?audio=sofa&type=2','a comfortable seat for several people','Phiên âm IPA: /ˈsoʊfə/ | \'sofa\' (noun): ghế dài, thường đặt trong phòng khách để ngồi nghỉ ngơi. Ví dụ: We sit on the sofa to watch TV.','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'sofa\' là gì?',NULL,'MULTIPLE_CHOICE'),(2,1,'bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15','ee31f557-1360-4d34-8919-248764c6b00e','https://dict.youdao.com/dictvoice?audio=brother&type=2','a male sibling','Phiên âm IPA: /ˈbrʌðər/ | \'brother\' (noun): anh trai hoặc em trai, người cùng cha mẹ. Ví dụ: Tom is my brother.','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'brother\' là gì?',NULL,'MULTIPLE_CHOICE'),(4,20,'37d53305-5705-458f-ada0-60fee4318321','f25b75c0-efba-4ba0-bb97-3fd141a8b86d',NULL,'repeated','Trạng từ thời gian \'yesterday\' xác định thời điểm trong quá khứ nên động từ phải chia ở thì Quá khứ đơn (repeated).','The clinical research team __________ the laboratory experiments twice yesterday before submitting their report.',NULL,'MULTIPLE_CHOICE'),(2,1,'b1704c0d-0dc1-49e6-b0c7-1aa595c8f906','f862c295-b86b-48f9-b323-da4ae61fe375','https://dict.youdao.com/dictvoice?audio=kitchen&type=2','the room where you cook meals','Phiên âm IPA: /ˈkɪtʃən/ | \'kitchen\' (noun): danh từ chỉ phòng trong nhà dùng để nấu ăn và chuẩn bị thực phẩm. Ví dụ: \"The kitchen is clean and bright.\"','Nối từ với nghĩa phù hợp: Định nghĩa chính xác nhất của từ \'kitchen\' là gì?',NULL,'MULTIPLE_CHOICE');
