INSERT INTO `assignments` VALUES (3,5,45,'2026-10-15 13:05:15.000000',NULL,'2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','2a4a0d9c-595a-499a-be62-6d440549c65f','19bf5cd2-a882-4f50-b660-2b982d7fafa0','Day 3 Essay: Opinion Essay on Online vs. Traditional Classroom Learning','Viết bài luận học thuật thể hiện quan điểm cá nhân (150 - 200 từ) về giáo dục trực tuyến và lớp học truyền thống.','WRITING',NULL,NULL),(5,5,30,'2026-10-15 13:05:15.000000',NULL,'2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','37d53305-5705-458f-ada0-60fee4318321','8491f7fd-b622-4f9b-8604-2a6b23a7fa4a','Day 1 Quiz: Present Perfect vs. Past Simple in Academic Contexts','Bài tập kiểm tra kiến thức phân biệt thì Hiện tại hoàn thành và Quá khứ đơn trong văn phong học thuật B1+.','GRAMMAR',NULL,NULL),(1,5,30,'2026-10-16 09:21:50.000000','2026-10-17 00:00:00.000000','2026-10-16 09:21:50.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','9b6dfda3-0798-459d-b9e0-b8d98ea66f6c',NULL,'Điền từ theo bài đọc (A1) - Ngày 2026-10-16','[READING PASSAGE]\nAnna lives in a quiet town. Every day she wakes up at 6:30 a.m. She brushes her teeth, eats a banana, and walks to the bus stop. On the bus Anna listens to her favourite pop songs. In the morning she also drinks a cup of tea before she starts work. At 7:15 a.m. she takes the bus to a small café near the centre. The café is called Green Leaf. Anna works there as a waitress. She serves coffee, tea, and fresh sandwiches to the customers. Her favourite drink to make is a cappuccino. During her break she helps clean the tables and talks with her colleagues. Anna\'s shift starts at 8:00 a.m. and ends at 4:00 p.m. After work she returns home, changes, and reads a book for an hour. In the evening she cooks dinner and goes to bed at 10:00 p.m.\n\n\n\n[Loại: READING] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','READING',NULL,NULL),(1,5,30,'2026-10-16 10:01:06.000000','2026-10-17 00:00:00.000000','2026-10-16 10:01:06.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','a7bb938c-486a-4b2e-9544-b27b1cac49d8',NULL,'Chia động từ (Verb Conjugation) (A1) - Ngày 2026-10-16','[READING PASSAGE]\nAnna lives in a quiet town. Every day she wakes up at 6:30 a.m. She brushes her teeth, eats a banana, and walks to the bus stop. On the bus Anna listens to her favourite pop songs. In the morning she also drinks a cup of tea before she starts work. At 7:15 a.m. she takes the bus to a small café near the centre. The café is called Green Leaf. Anna works there as a waitress. She serves coffee, tea, and fresh sandwiches to the customers. Her favourite drink to make is a cappuccino. During her break she helps clean the tables and talks with her colleagues. Anna\'s shift starts at 8:00 a.m. and ends at 4:00 p.m. After work she returns home, changes, and reads a book for an hour. In the evening she cooks dinner and goes to bed at 10:00 p.m.\n\n\n\n[Loại: GRAMMAR] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','GRAMMAR',NULL,NULL),(1,5,30,'2026-10-16 09:36:09.000000','2026-10-17 00:00:00.000000','2026-10-16 09:36:09.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','b1704c0d-0dc1-49e6-b0c7-1aa595c8f906',NULL,'Nối từ với nghĩa (A1) - Ngày 2026-10-16','[READING PASSAGE]\nAnna lives in a quiet town. Every day she wakes up at 6:30 a.m. She brushes her teeth, eats a banana, and walks to the bus stop. On the bus Anna listens to her favourite pop songs. In the morning she also drinks a cup of tea before she starts work. At 7:15 a.m. she takes the bus to a small café near the centre. The café is called Green Leaf. Anna works there as a waitress. She serves coffee, tea, and fresh sandwiches to the customers. Her favourite drink to make is a cappuccino. During her break she helps clean the tables and talks with her colleagues. Anna\'s shift starts at 8:00 a.m. and ends at 4:00 p.m. After work she returns home, changes, and reads a book for an hour. In the evening she cooks dinner and goes to bed at 10:00 p.m.\n\n\n\n[Loại: VOCABULARY] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','VOCABULARY',NULL,NULL),(1,5,30,'2026-10-16 11:01:45.000000','2026-10-17 00:00:00.000000','2026-10-16 11:01:45.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','bcafc78b-25ba-4bb1-b4c5-4180ab2b5a15',NULL,'Nối từ với nghĩa (A1) - Ngày 2026-10-16','\n\n[Loại: VOCABULARY] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','VOCABULARY',NULL,NULL),(5,5,35,'2026-10-15 13:05:15.000000',NULL,'2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','d99d43a2-b439-4b53-8bb6-3d8bf0eeff8a','fe0fbda0-b5ae-4f28-82d3-2dc7b13fecf6','Day 2 Practice: Technology and Modern Education - Reading Gap-Fill','Đọc đoạn văn học thuật về Công nghệ Giáo dục và điền từ vựng học thuật chính xác vào chỗ trống.','READING',NULL,NULL),(1,5,30,'2026-10-16 10:00:48.000000','2026-10-17 00:00:00.000000','2026-10-16 10:00:48.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','da5fc9fd-afd1-4298-bb9d-c6e4b7395986',NULL,'Nối từ với nghĩa (A1) - Ngày 2026-10-16','[READING PASSAGE]\nAnna lives in a quiet town. Every day she wakes up at 6:30 a.m. She brushes her teeth, eats a banana, and walks to the bus stop. On the bus Anna listens to her favourite pop songs. In the morning she also drinks a cup of tea before she starts work. At 7:15 a.m. she takes the bus to a small café near the centre. The café is called Green Leaf. Anna works there as a waitress. She serves coffee, tea, and fresh sandwiches to the customers. Her favourite drink to make is a cappuccino. During her break she helps clean the tables and talks with her colleagues. Anna\'s shift starts at 8:00 a.m. and ends at 4:00 p.m. After work she returns home, changes, and reads a book for an hour. In the evening she cooks dinner and goes to bed at 10:00 p.m.\n\n\n\n[Loại: VOCABULARY] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','VOCABULARY',NULL,NULL),(1,5,30,'2026-10-16 07:30:20.000000','2026-10-17 00:00:00.000000','2026-10-16 07:30:20.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','dcd05d71-9d3a-4ec1-8b0f-a19de5488187',NULL,'Nghe hội thoại (A1) - Ngày 2026-10-16','\n\n[Loại: LISTENING] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','LISTENING','https://pub-35c3a549c2974161a9d0e87abfbb7473.r2.dev/audio/c0bfb23b-7413-49c5-ba67-3d9d396d5cd7.wav','Speaker A: Hi, Lisa! Do you have any plans for the weekend?\nSpeaker B: Hi, Tom! I want to go to the cinema on Saturday.\nSpeaker A: Which film do you want to see?\nSpeaker B: I want to see the new comedy, \"Funny Day\".\nSpeaker A: That sounds good. The cinema is at 3 pm. Can we buy tickets now?\nSpeaker B: Yes, we can buy two tickets online.\nSpeaker A: Great! I will pay with my card.\nSpeaker A: Do you want popcorn and drinks?\nSpeaker B: Yes, please. One small popcorn and a cola.\nSpeaker A: OK, I will meet you at the cinema entrance at 2:45.\nSpeaker B: See you then. Bye!\nSpeaker A: Bye!'),(1,5,30,'2026-10-16 11:36:25.000000','2026-10-17 00:00:00.000000','2026-10-16 11:36:25.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','fba24678-3eed-47a4-8022-14761e73033e',NULL,'Định nghĩa -> Từ (A1) - Ngày 2026-10-16','\n\n[Loại: VOCABULARY] [Trình độ: A1] [Độ khó: MEDIUM] [Dự kiến: 30p] [Đối tượng: Tất cả học sinh]','VOCABULARY',NULL,NULL),(5,5,30,'2026-10-15 13:05:15.000000',NULL,'2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','fe7a5c29-c0b0-42ea-a065-ca8032ac9aff','2597a62e-70b2-4c38-9d7f-d614790b8856','Day 4 Speaking: Describing a Memorable Learning Experience & Shadowing','Luyện tập kỹ năng nói và ngữ âm thông qua trả lời câu hỏi và bài tập Shadowing theo chuẩn ngữ điệu quốc tế.','SPEAKING',NULL,NULL);
