INSERT INTO `lessons` VALUES (3,'2026-10-15 13:05:15.000000','2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','19bf5cd2-a882-4f50-b660-2b982d7fafa0','Lesson 03: Academic Essay Writing: Opinion Essay Structure','Comprehensive guidelines for IELTS Writing Task 2 opinion essays with high-band sample structures.','Structure a standard 4-paragraph opinion essay with clear thesis statement, topic sentences, and cohesive devices.'),(4,'2026-10-15 13:05:15.000000','2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','2597a62e-70b2-4c38-9d7f-d614790b8856','Lesson 04: Speaking Fluency & Pronunciation: Memorable Learning Experiences','Acoustic guidelines on stress patterns, connected speech, and academic monologue organization.','Enhance oral fluency, intonation, and phonemic precision through narrative storytelling and shadowing drills.'),(1,'2026-10-15 13:05:15.000000','2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','8491f7fd-b622-4f9b-8604-2a6b23a7fa4a','Lesson 01: Present Perfect vs. Past Simple in Academic Contexts','Detailed academic overview of tense usage in scholarly literature, research summaries, and data reporting.','Master the distinction between completed historical actions and ongoing or relevant research findings in academic writing.'),(2,'2026-10-15 13:05:15.000000','2026-10-15 13:05:15.000000','a6679afd-c8d4-4660-b6e9-12b34a2d222c','fe0fbda0-b5ae-4f28-82d3-2dc7b13fecf6','Lesson 02: Reading Comprehension: Technology and Modern Education','Analysis of modern educational paradigms, virtual classrooms, and AI-driven pedagogical tools.','Develop skimming and scanning skills to identify key lexical terms and factual information in academic texts on educational technology.');
